#define PI 3.141593
#define MAX_VOXELS 200
#define MAX_SHADOW_VOXELS 30
#define LEVELS 6
#define FDIST 0.5
//#define FISHEYE
#define FISHEYE_SCALE 2.
#define OCCUPANCY_THRESHOLD 0.95
#define SUBDIVISION_THRESHOLD 0.7
#define WIRE_WIDTH 0.1

#define MIN_SHADOW_DIST 1.
#define MAX_SHADOW_DIST 2.

#define WOOD_OCTAVES 7

struct Hit {
    float t;
    int mat;
    int level;
    vec3 n;
    vec3 id;
};


// math functions

uvec3 pcg3d(uvec3 v) {

    v = v * 1664525u + 1013904223u;

    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;

    v ^= v >> 16u;

    v.x += v.y*v.z;
    v.y += v.z*v.x;
    v.z += v.x*v.y;

    return v;
}

uvec4 pcg4d(uvec4 v)
{
    v = v * 1664525u + 1013904223u;

    v.x += v.y*v.w;
    v.y += v.z*v.x;
    v.z += v.x*v.y;
    v.w += v.y*v.z;

    v ^= v >> 16u;

    v.x += v.y*v.w;
    v.y += v.z*v.x;
    v.z += v.x*v.y;
    v.w += v.y*v.z;

    return v;
}

vec3 noise3d(ivec3 v) {
    return vec3(pcg3d(uvec3(v))) * (1.0 / float(0xffffffffu));
}

vec4 noise4d(ivec4 v) {
    return vec4(pcg4d(uvec4(v))) * (1.0 / float(0xffffffffu));
}

vec3 safe_inverse(in vec3 rd) {
    vec3 sg = abs(sign(rd));
    return (1e6 * (1.0-sg) + sg) / (rd + (1.0 - sg));
}

// octree stuff

bool tower_occupancy(in vec3 pos) {
    return length(fract(0.25 * pos.xy) - 0.5) < 0.3;
}

bool subdivision(in ivec3 id, int level) {
    vec3 pos = vec3(id) / float(1 << level);
    float thresh = tower_occupancy(pos) ? SUBDIVISION_THRESHOLD / 2. : SUBDIVISION_THRESHOLD;
    return noise4d(ivec4(id, level + LEVELS)).x > thresh;
}

bool occupancy(in ivec3 id, int level) {
    vec3 pos = vec3(id) / float(1 << level);
    bool lax = subdivision(id, level) || level > 0;
    bool strict = noise4d(ivec4(id, level)).x > smoothstep(-10., 5., abs(pos.z + 2.) - 2.) * OCCUPANCY_THRESHOLD;
    bool cond = tower_occupancy(pos);
    return cond || strict;
}

// OCTREE TRAVERSAL
// adapted from abje's octree algorithm: https://www.shadertoy.com/view/4sVfWw

// trace primary rays
Hit voxtrace(in vec3 ro, in vec3 rd) {
    Hit h;
    h.mat = 0;
    h.t = 0.;
    h.level = 0;
    h.n = vec3(1., 0., 0.);
    float sl = 1.0;
    h.id = floor(ro);
    vec3 p = ro; // follows the ray to decide which child cells we end up in
    vec3 ri = safe_inverse(rd);
    vec3 rs = sign(ri);
    vec3 rsi = ri * rs;
    vec3 dis = vec3(0.0);
    vec3 rda = abs(rd);
    vec3 mm = vec3(0.);
    bool initializing = true;
    bool exiting = false;
    vec3 prevId = h.id;
    vec3 prevNorm = h.n;
    float t_internal = 1000000.;

    for (int i=0; i<MAX_VOXELS; i++) {
        bool continuing = true;
        bool exitingNow = false;
        //bool passed = false; // debug
        if (exiting && h.level > 0) { // exiting up one level of the octree
            exitingNow = true;
            --h.level;
            sl *= 2.0;
            h.id = floor(h.id / 2.0);
            prevId = floor(prevId / 2.0);
            // check if we are still at the boundary of parent cells; if so, exit again
            exiting = h.level > 0 && !all(equal(floor(prevId / 2.0), floor(h.id / 2.0)));
            continuing = false;

        } else if (occupancy(ivec3(h.id), h.level)) { // occupied cell
            if (initializing) {
                vec3 centerOffset = abs(ro - (h.id+.5)*sl);
                initializing = false;
                mm = step(centerOffset.yzx, centerOffset.xyz) * step(centerOffset.zxy, centerOffset.xyz);
            }
            float width = WIRE_WIDTH * sl;

            dis = (h.id*sl - ro + sl * (0.5 + rs*0.5)) * ri;
            float t_out = min ( dis.x, min ( dis.y, dis.z ) );

            vec3 mm_inner = mm;
            float t_internal_curr = h.t;
            vec3 norm = prevNorm;
            h.mat = 1;

            for (int k=0; k<2; ++k) {

                mat3x2 proj = transpose(mat2x3(mm_inner.zxy, mm_inner.yzx));
                // 2D smaller square intersection
                vec2 proj_ri = proj * ri;
                vec2 proj_sign_term = sl * (0.5 - WIRE_WIDTH) * (proj * rs) * proj_ri;
                vec2 proj_cell_term = ((proj * h.id) * sl - proj * ro + sl * 0.5) * proj_ri;
                vec2 dis2 = proj_cell_term + proj_sign_term;
                vec2 dis2_in = proj_cell_term - proj_sign_term;
                float t_in_new = max(dis2_in.x, dis2_in.y);
                float t_out_new = min(dis2.x, dis2.y);

                if (t_out_new < t_internal_curr || (t_in_new > t_internal_curr && t_in_new > 0.)) {
                    break;
                } else if (t_out_new > t_out) {
                    t_internal_curr = 1000000.;
                    h.mat = 0;
                    break;
                }
                h.mat = 2;
                t_internal_curr = t_out_new;
                vec2 mm2 = step(dis2.xy, dis2.yx);
                mm_inner = transpose(proj) * mm2;
                norm = -mm_inner * rs;

            }
            if (t_internal_curr < t_internal && t_internal_curr > 0.) {
                t_internal = t_internal_curr;
                h.n = norm;
            }
        }

        if (h.mat != 1 && !exitingNow && subdivision(ivec3(h.id), h.level) && h.level < LEVELS) { // going down one level in the octree
            ++h.level;
            vec3 pf = p - h.id * sl;
            sl *= 0.5;
            h.id =  h.id*2.0 + step(sl, pf);
            continuing = false;
        }

        if (continuing) { // traverse empty cell
            initializing = false;
            prevId = h.id;
            dis = (h.id*sl - ro + sl * (0.5 + rs*0.5)) * ri;
            h.t = min ( dis.x, min ( dis.y, dis.z ) );
            if (t_internal < h.t && t_internal > 0.) {
                h.t = t_internal;
                h.mat = 1;
                break;
            }
            h.mat = 0;
            p = ro + rd * h.t;
            mm = step(dis.xyz, dis.yzx) * step(dis.xyz, dis.zxy);
            h.id += mm * rs;
            prevNorm = -mm*rs;
            // check if we are at the boundary of parent cells; if so, exit
            exiting = !all(equal(floor(prevId / 2.0), floor(h.id / 2.0)));
        }
    }
    return h;
}

// octree traversal for shadows
float shadowtrace(in vec3 ro, in vec3 rd, bool selfShadow) {
    float t = 0.;
    int level = 0;
    float sl = 1.0;
    vec3 id = floor(ro);
    vec3 p = ro; // follows the ray to decide which child cells we end up in
    vec3 ri = safe_inverse(rd);
    vec3 rs = sign(ri);
    vec3 rsi = ri * rs;
    vec3 dis = vec3(0.0);
    vec3 rda = abs(rd);
    vec3 mm = vec3(0.);
    bool initializing = true;
    bool exiting = false;
    vec3 prevId = id;

    float shadowFac = 1.0;

    float t_internal = 1000000.;
    int mat = 0;

    for (int i=0; i<MAX_SHADOW_VOXELS; i++) {
        bool continuing = true;
        bool exitingNow = false;
        //bool passed = false; // debug
        if (exiting && level > 0) { // exiting up one level of the octree
            exitingNow = true;
            --level;
            sl *= 2.0;
            id = floor(id / 2.0);
            prevId = floor(prevId / 2.0);
            // check if we are still at the boundary of parent cells; if so, exit again
            exiting = level > 0 && !all(equal(floor(prevId / 2.0), floor(id / 2.0)));
            continuing = false;

        } else if (occupancy(ivec3(id), level)) { // occupied cell
            if (initializing) {
                vec3 centerOffset = abs(ro - (id+.5)*sl);
                initializing = false;
                mm = step(centerOffset.yzx, centerOffset.xyz) * step(centerOffset.zxy, centerOffset.xyz);
            }
            float width = WIRE_WIDTH * sl;

            dis = (id*sl - ro + sl * (0.5 + rs*0.5)) * ri;
            float t_out = min ( dis.x, min ( dis.y, dis.z ) );

            vec3 mm_inner = mm;
            float t_internal_curr = t;
            mat = 1;
            float opacity = 1.-smoothstep(MIN_SHADOW_DIST, MAX_SHADOW_DIST, t);
            shadowFac *= 1.-opacity;

            for (int k=0; k<2; ++k) {

                mat3x2 proj = transpose(mat2x3(mm_inner.zxy, mm_inner.yzx));
                // 2D smaller square intersection
                vec2 proj_ri = proj * ri;
                vec2 proj_sign_term = sl * (0.5 - WIRE_WIDTH) * (proj * rs) * proj_ri;
                vec2 proj_cell_term = ((proj * id) * sl - proj * ro + sl * 0.5) * proj_ri;
                vec2 dis2 = proj_cell_term + proj_sign_term;
                vec2 dis2_in = proj_cell_term - proj_sign_term;
                float t_in_new = max(dis2_in.x, dis2_in.y);
                float t_out_new = min(dis2.x, dis2.y);

                if (t_out_new < t_internal_curr || (t_in_new > t_internal_curr && t_in_new > 0.)) {
                    break;
                } else if (t_out_new > t_out) {
                    t_internal_curr = 1000000.;
                    mat = 0;
                    shadowFac = 1.0;
                    break;
                }
                mat = 2;
                t_internal_curr = t_out_new;
                vec2 mm2 = step(dis2.xy, dis2.yx);
                mm_inner = transpose(proj) * mm2;

            }
            if (t_internal_curr < t_internal && t_internal_curr > 0.) {
                t_internal = t_internal_curr;
            }
        }

        if (mat != 1 && !exitingNow && subdivision(ivec3(id), level) && level < LEVELS) { // going down one level in the octree
            ++level;
            vec3 pf = p - id * sl;
            sl *= 0.5;
            id =  id*2.0 + step(sl, pf);
            continuing = false;
        }

        if (continuing) { // traverse empty cell
            initializing = false;
            prevId = id;
            dis = (id*sl - ro + sl * (0.5 + rs*0.5)) * ri;
            t = min ( dis.x, min ( dis.y, dis.z ) );
            if (t_internal < t && t_internal > 0.) {
                t = t_internal;
                mat = 1;
                break;
            }
            mat = 0;
            p = ro + rd * t;
            mm = step(dis.xyz, dis.yzx) * step(dis.xyz, dis.zxy);
            id += mm * rs;
            // check if we are at the boundary of parent cells; if so, exit
            exiting = !all(equal(floor(prevId / 2.0), floor(id / 2.0)));
        }
    }
    return shadowFac;
}

// wood material by Dean the Coder (https://www.shadertoy.com/view/mdy3R1)
// with fract(sin()) noise replaced by PCG noise functions
#define sat(x)	clamp(x, 0., 1.)
#define S(a, b, c)	smoothstep(a, b, c)
#define S01(a)	S(0., 1., a)

float sum2(vec2 v) { return dot(v, vec2(1)); }

///////////////////////////////////////////////////////////////////////////////

// vec3 noise3d(ivec3 v)

/*float h31(vec3 p3) {
	p3 = fract(p3 * .1031);
	p3 += dot(p3, p3.yzx + 333.3456);
	return fract(sum2(p3.xy) * p3.z);
}*/
float h31(vec3 p3) {
    return noise3d(floatBitsToInt(p3)).x;
}

float h21(vec2 p) { return h31(p.xyx); }

float n31(vec3 p) {
	const vec3 s = vec3(7, 157, 113);

	// Thanks Shane - https://www.shadertoy.com/view/lstGRB
	vec3 ip = floor(p);
	p = fract(p);
	p = p * p * (3. - 2. * p);
	vec4 h = vec4(0, s.yz, sum2(s.yz)) + dot(ip, s);
    //h = mix(noise4d(floatBitsToInt(h)), noise4d(floatBitsToInt(h + s.x)), p.x);
	h = mix(fract(sin(h) * 43758.545), fract(sin(h + s.x) * 43758.545), p.x);
	h.xy = mix(h.xz, h.yw, p.y);
	return mix(h.x, h.y, p.z);
}

// roughness: (0.0, 1.0], default: 0.5
// Returns unsigned noise [0.0, 1.0]
float fbm(vec3 p, int octaves, float roughness) {
	float sum = 0.,
	      amp = 1.,
	      tot = 0.;
	roughness = sat(roughness);
	for (int i = 0; i < octaves; i++) {
		sum += amp * n31(p);
		tot += amp;
		amp *= roughness;
		p *= 2.;
	}
	return sum / tot;
}

vec3 randomPos(float seed) {
	vec4 s = vec4(seed, 0, 1, 2);
	return vec3(h21(s.xy), h21(s.xz), h21(s.xw)) * 1e2 + 1e2;
}

// Returns unsigned noise [0.0, 1.0]
float fbmDistorted(vec3 p) {
	p += (vec3(n31(p + randomPos(0.)), n31(p + randomPos(1.)), n31(p + randomPos(2.))) * 2. - 1.) * 1.12;
	return fbm(p, WOOD_OCTAVES, .5);
}

// vec3: detail(/octaves), dimension(/inverse contrast), lacunarity
// Returns signed noise.
float musgraveFbm(vec3 p, float octaves, float dimension, float lacunarity) {
	float sum = 0.,
	      amp = 1.,
	      m = pow(lacunarity, -dimension);
	for (float i = 0.; i < octaves; i++) {
		float n = n31(p) * 2. - 1.;
		sum += n * amp;
		amp *= m;
		p *= lacunarity;
	}
	return sum;
}

// Wave noise along X axis.
vec3 waveFbmX(vec3 p) {
	float n = p.x * 20.;
	n += .4 * fbm(p * 3., 3, 3.);
	return vec3(sin(n) * .5 + .5, p.yz);
}

///////////////////////////////////////////////////////////////////////////////
// Math
float remap01(float f, float in1, float in2) { return sat((f - in1) / (in2 - in1)); }

///////////////////////////////////////////////////////////////////////////////
// Wood material.
vec3 matWood(vec3 p) {
	float n1 = fbmDistorted(p * vec3(7.8, 1.17, 1.17));
	n1 = mix(n1, 1., .2);
	float n2 = mix(musgraveFbm(vec3(n1 * 4.6), float(WOOD_OCTAVES), 0., 2.5), n1, .85),
	      dirt = 1. - musgraveFbm(waveFbmX(p * vec3(.01, .15, .15)), float(WOOD_OCTAVES*2), .26, 2.4) * .4;
	float grain = 1. - S(.2, 1., musgraveFbm(p * vec3(500, 6, 1), 2., 2., 2.5)) * .2;
	n2 *= dirt * grain;

    // The three vec3 values are the RGB wood colors - Tweak to suit.
	return mix(mix(vec3(.03, .012, .003), vec3(.25, .11, .04), remap01(n2, .19, .56)), vec3(.52, .32, .19), remap01(n2, .56, 1.));
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // camera initialization
    float scaledtime = iTime  * 0.5;
    float scaled_scaledtime = mix(scaledtime, scaledtime * 0.5, smoothstep(0., 24., scaledtime));
    float mouseY = iMouse.y < 1. ? -sin(scaledtime*0.25) : (0.5-iMouse.y/iResolution.y) * PI;
    float mouseX = iMouse.x < 1. ? -scaledtime*0.25 + 3.14*0.75 : -(iMouse.x/iResolution.x) * 2. * PI;
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.x;
	vec3 eye = vec3(cos(scaled_scaledtime / 10.) * 10., scaled_scaledtime * 0.4, sin(scaled_scaledtime / 10.) * 10.);
    vec3 w = vec3(cos(mouseX) * cos(mouseY), sin(mouseX) * cos(mouseY), -sin(mouseY));
    vec3 u = normalize(cross(w, vec3(0., 0., 1.)));
    vec3 v = cross(u, w);

    #ifdef FISHEYE
    uv *= FISHEYE_SCALE;
    vec2 c = cos(uv);
    vec2 s = sin(uv);
    float r2 = dot(uv, uv);
    //vec3 rd = normalize(uv.x * u + uv.y * v + sqrt(1.-r2) * w); // true fisheye
    vec3 rd = normalize(s.x * c.y * u + s.y * v + c.x * c.y * w); // spherical map projection (can have 360 vision if FISHEYE_SCALE is high enough)
    #else
    vec3 rd = normalize(FDIST*w + uv.x*u + uv.y*v);
    #endif

    // raytrace
    Hit h = voxtrace(eye, rd);

    //coloring
    vec3 fogCol = vec3(0.6, 0.8, 1.0);
    vec3 col = fogCol * 0.5;
    if (h.mat > 0) {
        vec3 lightdir = normalize(vec3(1., 2., 3.));

        vec3 p = eye + rd * h.t;
        float shadowfac = max(0., dot(h.n, lightdir));
        if (shadowfac > 1e-5) {
            bool selfShadow = h.mat == 2;
            shadowfac *= shadowtrace(p + lightdir * 1e-5, lightdir, selfShadow);
        }
        vec3 albedo = mix(matWood(p * exp2(float(h.level))), vec3(1., 1., 0.6), 0.1);

        vec3 col1 = albedo * mix(shadowfac, 1., 0.05);
        vec3 col2 = albedo * max(0., dot(h.n, -lightdir)) * vec3(0.1, 0.1, 0.2);
        col = col1 + col2;
        float fogFac = exp(-0.01 * h.t);//1.-max(1.0 - h.t * 0.015, 0.);
        col = mix(fogCol, col, fogFac);
    }
    //if (h.mat == 2) col = h.n*.5+.5;
    //if (h.mat == 3) col = vec3(0., 1., 0.);
    //col = vec3(h.t) / 5.;
    //fragColor = vec4(col / (col + 1.)*3., 1.);
    fragColor = vec4(pow(col*1.5, vec3(0.45)), 1.);
}
